import{createRecipeDraft,ingredientFromPortion,validateRecipe}from'../../recipe-model.js';import{calculateRecipeNutrition}from'../../recipe-nutrition.js';
export function fixtureRecipe(name='Moje curry',yieldInfo={servings:5,finalWeight:1250,finalVolume:2000}){const d=createRecipeDraft(name),product={id:'custom:recipe-fixture',source:'custom',sourceId:'recipe-fixture',name:'Składnik',unit:'g',brand:null,barcode:null,per100:{kcal:100,protein:10,fat:2,carbs:12}};d.ingredients=[ingredientFromPortion({product,amount:1000,nutrition:{kcal:1000,protein:100,fat:20,carbs:120}})];d.yield=yieldInfo;d.nutrition=calculateRecipeNutrition(d.ingredients,d.yield);d.status='READY';return validateRecipe(d);}
export function memoryStorage(){let state={products:[],searches:[],usage:[],selections:[],meta:[],recipes:[],recipeDrafts:[],recipeHistory:[]};return {read:async(name,key)=>structuredClone(key===undefined?state[name]:state[name].find(r=>r.key===key)),transact:async(names,fn)=>{const next=structuredClone(state),result=fn(next);state=next;return structuredClone(result);},snapshot:async()=>structuredClone(state),replace:async next=>{state=structuredClone(next);},mutate:async(name,key,fn)=>{const row=fn(state[name].find(r=>r.key===key));state[name]=state[name].filter(r=>r.key!==key);if(row)state[name].push({...row,key});},close:async()=>{}};}
